data class Note(val id: Long, val titre: String)

interface NotesLocal {
    fun observer(): Flow<List<Note>>
}

interface NotesDistant {
    suspend fun recuperer(): List<Note>
}

class NotesDepot(
    private val local: NotesLocal,
    private val distant: NotesDistant,
    private val enregistrer: suspend (List<Note>) -> Unit,
) {
    fun notes(): Flow<List<Note>> = local.observer()

    suspend fun actualiser() {
        enregistrer(distant.recuperer())
    }
}

class Conteneur(context: Context) {
    private val appContext = context.applicationContext

    val depot: PreferencesDepot by lazy { PreferencesDepot(appContext) }
}

class PreferencesDepot(private val context: Context)

data class AccueilUiState(val notes: List<Note> = emptyList(), val chargement: Boolean = true)

class AccueilViewModel(depot: NotesDepot) : ViewModel() {
    val uiState: StateFlow<AccueilUiState> = depot.notes()
        .map { AccueilUiState(notes = it, chargement = false) }
        .stateIn(
            scope = viewModelScope,
            started = SharingStarted.WhileSubscribed(5_000),
            initialValue = AccueilUiState(),
        )
}

