    @Query("SELECT * FROM fiches WHERE titre LIKE '%' || :terme || '%' OR contenu LIKE '%' || :terme || '%'")
    fun rechercher(terme: String): Flow<List<Fiche>>

    @Upsert
    suspend fun enregistrer(fiche: Fiche)

    @Delete
    suspend fun supprimer(fiche: Fiche)
}

data class FicheSimple(val titre: String, val favori: Boolean)

fun filtrer(fiches: List<FicheSimple>, terme: String, favorisSeuls: Boolean): List<FicheSimple> =
    fiches
        .filter { !favorisSeuls || it.favori }
        .filter { it.titre.contains(terme.trim(), ignoreCase = true) }

fun main() {
    val fiches = listOf(
        FicheSimple("Coroutines", true),
        FicheSimple("Room", false),
        FicheSimple("Flow et coroutines", false),
    )

    println(filtrer(fiches, "coroutines", false).map { it.titre })
    println(filtrer(fiches, " COROUTINES ", true).map { it.titre })
}

