int progression(List<bool> etapes) {
  if (etapes.isEmpty) return 0;
  final faites = etapes.where((etape) => etape).length;
  return (faites * 100 / etapes.length).round();
}

void main() {
  print(progression([true, true, false, false]));
  print(progression([true, false, false]));
  print(progression([]));
}

