fun resoudre(local: Version, distant: Version, baseCommune: Int): String = when {
    local.base == baseCommune && distant.base == baseCommune -> "aucun changement"
    distant.base == baseCommune -> "garder le local"
    local.base == baseCommune -> "garder le distant"
    else -> "conflit : demander à l'utilisateur"
}

fun main() {
    val base = 3
    println(resoudre(Version("A", 3, 10), Version("A", 3, 10), base))
    println(resoudre(Version("B", 4, 20), Version("A", 3, 10), base))
    println(resoudre(Version("B", 4, 20), Version("C", 4, 30), base))
}

data class Requete(val utilisateur: String?, val proprietaire: String)

fun autoriser(requete: Requete): Int = when {
    requete.utilisateur == null -> 401
    requete.utilisateur != requete.proprietaire -> 403
    else -> 200
}

fun main() {
    println(autoriser(Requete(null, "ana")))
    println(autoriser(Requete("leo", "ana")))
    println(autoriser(Requete("ana", "ana")))
}

fun niveau(points: Int): Int {
    require(points >= 0) { "Points négatifs" }
    return points / 100 + 1
}

fun verifier(nom: String, condition: Boolean) {
    println("${if (condition) "OK" else "ÉCHEC"} : $nom")
}

fun main() {
    verifier("zéro point donne le niveau 1", niveau(0) == 1)
    verifier("99 points restent au niveau 1", niveau(99) == 1)
    verifier("100 points donnent le niveau 2", niveau(100) == 2)
    verifier("négatif refusé", runCatching { niveau(-1) }.isFailure)
}

