fun mediane(valeurs: List<Int>): Double {
    val triees = valeurs.sorted()
    val milieu = triees.size / 2
    return if (triees.size % 2 == 1) {
        triees[milieu].toDouble()
    } else {
        (triees[milieu - 1] + triees[milieu]) / 2.0
    }
}

fun main() {
    println(mediane(listOf(910, 880, 2400, 900, 870)))
    println(mediane(listOf(910, 880, 900, 870)))
}

